function P = subsasgn(P,s,varargin)
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% P = SUBSASGN(P,S,VAL) assigns into a 'cdopvar': dot assignment is the
% builtin, except for the field names of the 1-D and 2-D layouts described
% below; paren assignment P(...) = VAL is an error.
%
% INPUTS
% - P:    'cdopvar' object, or [] when P(...) = VAL creates a variable;
% - s:    substruct of the indexing expression, generated by MATLAB;
% - varargin: the value(s) assigned; more than one for a comma-list
%           assignment such as [P.C{1:2}] = deal(a,b);
%
% OUTPUTS
% - P:    the modified object.
%
% NOTES
% Why an error: the builtin Q(1,2) = P builds a 1 x 2 ARRAY of cdopvar
% objects, on which the overloaded 'size' and every container method then
% fail or misread it; nothing in the class accepts an object array.
% Q(1) = P, Q(:) = P and Q(1) = [] are rejected with it. Blocks are
% assigned with P.C{i,j} = X, unchanged. Assigning a container INTO a cell
% or a struct field (c{k} = P, s.f = P) does not call this method.
%
% Cost (measured, R2025b): called for every assignment into a cdopvar
% outside the class methods, 12-14 us each, independent of q.
% - A direct edit of a local container is in place: P.dim_out(1) = k,
%   P.Zd = Zd, and P.C{i,j} = X, which replaces the block without copying.
% - A NESTED indexed edit into a block also calls the subsasgn of the
%   block with the block as a shared temporary, which COPIES the edited
%   leaf on every assignment: P.C{i,j}.params.B{k}(r,c) = v is
%   O(nnz(B{k})) (1.1 ms at q = 2e6, nnz 3.9e5) and P.C{i,j}.Zd{i} = name
%   is O(q) (23 ms at q = 2e6), against 31 us and 1.4 us without the
%   overloads.
% - For such an edit, extract, clear, edit, reinsert, which edits the
%   block in place (53-93 us per edit for q = 1e5 to 2e6):
%       X = P.C{i,j};  P.C{i,j} = [];  X.params.B{k}(r,c) = v;  P.C{i,j} = X;
%
% The fields of the 2025 'dopvar' (P, Q1, Q2, R) and 'dopvar2d' (R00 to
% R22), and I, var1, var2, are set in a container with that structure:
% P.Q1 = X, P.R.R1 = X and P.R22{2,3} = X set that component or parameter;
% P.Q1(1,2) = X reads the field, assigns into it and sets it. The first
% such assignment of a session warns ('cdopvar:opvarField') that these are
% not fields of the class, and that this support may be dropped in future
% versions.
%
% See also SUBSREF, CDOPVAR.
%
% For support, contact M. Peet, Arizona State University at mpeet@asu.edu

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% PIETOOLS - subsasgn(cdopvar)
%
% Copyright (C) 2026 PIETOOLS Team
%
% This program is free software; you can redistribute it and/or modify
% it under the terms of the GNU General Public License as published by
% the Free Software Foundation; either version 2 of the License, or
% (at your option) any later version.
%
% This program is distributed in the hope that it will be useful,
% but WITHOUT ANY WARRANTY; without even the implied warranty of
% MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the
% GNU General Public License for more details.
%
% You should have received a copy of the GNU General Public License
% along with this program; if not, write to the Free Software
% Foundation, Inc., 59 Temple Place, Suite 330, Boston, MA  02111-1307  USA
%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%
% If you modify this code, document all changes carefully and include date
% authorship, and a brief description of modifications
%
% Initial coding MMP, 09/29/2026

if strcmp(s(1).type,'()')
    error('cdopvar:parenAssign',['Paren assignment P(...) = X is not '...
        'supported for cdopvar: it would build an array of containers or '...
        'index one, which no container method accepts. Assign block (i,j) '...
        'with P.C{i,j} = X.'])
end
% The builtin called from this method has the access of the class, so it
% would set protected properties that P.name = X outside the class may
% not. Raise the error of the builtin for them, same identifier and text.
% Names come from the metaclass, once.
persistent hidden
if ~iscell(hidden)
    mc = ?cdopvar;   pl = mc.PropertyList;
    hidden = {pl(~cellfun(@(a) isequal(a,'public'),{pl.SetAccess})).Name};
end
if strcmp(s(1).type,'.') && any(strcmp(s(1).subs,hidden))
    error(message('MATLAB:class:SetProhibited',s(1).subs,'''cdopvar'''))
end
% Support setting fields of the 1-D or 2-D layout, which are
% not actual properties of the class.
f1 = {'P','Q1','Q2','R'};
f2 = {'R00','R0x','R0y','R02','Rx0','Rxx','Rxy','Rx2',...
      'Ry0','Ryx','Ryy','Ry2','R20','R2x','R2y','R22'};
f0 = {'I','var1','var2','dim'};                 % fields of both classes
persistent warned                               % warning below given once
if strcmp(s(1).type,'.') && any(strcmp(s(1).subs,[f0,f1,f2]))
    fname = s(1).subs;
    if ~isscalar(varargin)
        error('cdopvar:fieldListAssign','Assign one value to the field ''%s''.',fname)
    end
    val = varargin{1};
    % A shared field is set as in the 1-D layout if P has it and the
    % value has one variable
    if any(strcmp(fname,f0))
        use1 = is_opvar1d(P) && size(val,1)<=1;
    else
        use1 = any(strcmp(fname,f1));
    end
    if use1 && ~is_opvar1d(P)
        error('cdopvar:notOpvar1d',['''%s'' belongs to the 1-D field layout (P, Q1, Q2, R), but this cdopvar does not have that layout: '...
            'it needs at most one spatial variable, and R blocks before L2 blocks (see is_opvar1d).'],fname)
    elseif ~use1 && ~is_opvar2d(P) && any(strcmp(fname,f2))
        error('cdopvar:notOpvar2d',['''%s'' belongs to the 2-D field layout (R00 to R22), but this cdopvar does not have that layout: '...
            'it needs at most two spatial variables, and blocks ordered R, L2[x], L2[y], L2[x,y] (see is_opvar2d).'],fname)
    elseif ~use1 && ~is_opvar2d(P)
        error('cdopvar:notOpvar',['''%s'' belongs to the 1-D or 2-D field layout, but this cdopvar has neither: '...
            'it needs at most two spatial variables, and blocks ordered R, L2[x], L2[y], L2[x,y] (see is_opvar2d).'],fname)
    end
    % The target: the field, one of R.R0-R.R2, or one parameter R22{i,j};
    % deeper indexing, P.Q1(1,2) = X, assigns into the current value
    target = fname;     cidx = [];      rest = s(2:end);
    if ~isempty(rest) && strcmp(fname,'R') && strcmp(rest(1).type,'.') && any(strcmp(rest(1).subs,{'R0','R1','R2'}))
        target = ['R.',rest(1).subs];   rest = rest(2:end);
    elseif ~isempty(rest) && any(strcmp(fname,f2)) && strcmp(rest(1).type,'{}')
        cidx = rest(1).subs;            rest = rest(2:end);
    end
    % Remaining subscripts: assign into the current value of the target
    if ~isempty(rest)
        if use1,    cur = getfield_opvar1d(P,target);
        else,       cur = getfield_opvar2d(P,target);
        end
        if ~isempty(cidx),  cur = cur{cidx{:}};     end
        val = subsasgn(cur,rest,val);
    end
    % Write the value into the blocks: 1-D or 2-D
    % layout, the latter labelled with the parameter index for messages
    if use1
        P = setfield_opvar1d(P,target,val);
    else
        lab = target;
        if ~isempty(cidx),  lab = sprintf('%s{%s}',target,strjoin(cellfun(@num2str,cidx,'UniformOutput',false),','));  end
        P = setfield_opvar2d(P,target,val,cidx,struct('label',lab));
    end
    % Not a property, and this support may be dropped: say so, once per
    % session so that loops over fields are not flooded
    if isempty(warned)
        warned = true;
        warning('cdopvar:opvarField',['A cdopvar has no field ''%s''; setting it changes the blocks as in the 1-D or 2-D field layout. '...
            'Setting components this way may not be supported in future versions.'],fname)
    end
    return
end
% Any other assignment: the builtin
P = builtin('subsasgn',P,s,varargin{:});

end
